
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mn12_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mn12_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.355509676193210e+00, -6.246528600958178e+00, -6.083361418985105e+00, -5.837385850055974e+00, -5.466413751867280e+00, -4.916254588756969e+00, -4.145209243375233e+00, -3.202116999033108e+00, -2.273271837202660e+00, -1.298239956879416e+00, -3.769175766844700e-01, -4.953495392641617e-01, -5.918903448542847e-01, -4.966687333055725e-01, -3.397625662158033e-01, -2.431096775991382e-01, -1.566084631386054e-01, -1.015322967331802e-01, -2.724977505212037e-02, -3.157815350669438e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


